operations.schema:
input SetConnectorInput {
    connectorId: String!
    authType: ConnectionAuthType!
}

input SetSecretRefInput {
    id: OID!
    name: String!
    ref: String!
}

operations.reducer:
const existing = state.secretRefs.find(
    (secretRef) => secretRef.name === action.input.name,
);
if (existing) {
    existing.ref = action.input.ref;
} else {
    state.secretRefs.push({
        id: action.input.id,
        name: action.input.name,
        ref: action.input.ref,
    });
}

const index = state.secretRefs.findIndex(
    (secretRef) => secretRef.id === action.input.id,
);
if (index === -1) {
    throw new SecretRefNotFoundError("Secret ref not found");
}
state.secretRefs.splice(index, 1);

operations.schema:
input RecordCheckResultInput {
    status: ConnectionStatus!
    checkedAt: DateTime!
    error: String
}

operations.reducer:
state.status = action.input.status;
state.lastCheckedAt = action.input.checkedAt;
state.lastError = action.input.error || null;
